import { defineComponent, computed, h, onMounted, ref, useId, type PropType } from 'vue';
import { getInputIds, getInputAriaProps } from '../lib/core';
import type { InputBaseProps } from '../lib/core';
import styles from './input.module.scss';

export const Input = defineComponent({
	name: 'Input',
	inheritAttrs: false,
	props: {
		label: String,
		error: String,
		helperText: String,
		controlSize: String as PropType<InputBaseProps['controlSize']>,
		required: { type: Boolean, default: false },
		id: String,
		type: { type: String, default: 'text' },
		placeholder: String,
		modelValue: String,
		defaultValue: String,
		readOnly: { type: Boolean, default: false },
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue'],
	setup(props, { emit, attrs }) {
		const fallbackId = useId();
		const inputId = computed(() => props.id || fallbackId);
		const ids = computed(() => getInputIds(inputId.value));
		const ariaProps = computed(() => getInputAriaProps(ids.value, props.error, props.helperText));
		const inputEl = ref<HTMLInputElement | null>(null);

		onMounted(() => {
			if (!inputEl.value) return;
			if (props.modelValue === undefined && props.defaultValue !== undefined) {
				inputEl.value.value = props.defaultValue;
			}
		});

		function onInput(event: Event) {
			emit('update:modelValue', (event.target as HTMLInputElement).value);
		}

		return () => {
			const children: any[] = [];

			if (props.label) {
				children.push(
					h(
						'label',
						{
							for: inputId.value,
							class: [styles.label, props.required ? styles.required : ''],
						},
						props.label,
					),
				);
			}

			children.push(
				h('input', {
					...attrs,
					ref: inputEl,
					id: inputId.value,
					type: props.type,
					class: [styles.input, props.error ? styles.error : '', attrs.class],
					'data-control-size': props.controlSize,
					value: props.modelValue,
					placeholder: props.placeholder,
					readonly: props.readOnly,
					disabled: props.disabled,
					required: props.required,
					'aria-invalid': ariaProps.value['aria-invalid'],
					'aria-describedby': ariaProps.value['aria-describedby'],
					onInput: [attrs.onInput, onInput].filter(Boolean),
				}),
			);

			if (props.error) {
				children.push(h('span', { id: ids.value.error, class: styles.errorText }, props.error));
			} else if (props.helperText) {
				children.push(h('span', { id: ids.value.helper, class: styles.helperText }, props.helperText));
			}

			return h('div', { class: styles.inputWrapper }, children);
		};
	},
});

export default Input;

@use '../../../styles/variables/colors' as *;

.inputWrapper {
	display: flex;
	flex-direction: column;
	gap: var(--tile-input-label-gap, #{$spacing-1});
	width: 100%;

	&:has(> input:only-child) {
		display: var(--tile-input-bare-wrapper-display, flex);
	}
}

.input {
	display: var(--tile-input-display, flex);
	gap: var(--tile-input-gap, normal);
	height: var(--tile-input-height, 2.25rem);
	width: 100%;
	border-radius: var(--tile-input-radius, #{$radius});
	border: var(--tile-input-border-width, 1px) solid var(--tile-input-border, #{$border});
	background-color: var(--tile-input-background, #{$background});
	padding: 0 var(--tile-input-padding-inline, #{$spacing-3});
	font-size: var(--tile-input-font-size, #{$text-sm});
	line-height: var(--tile-input-line-height, inherit);
	box-shadow: var(--tile-input-shadow, none);
	color: $foreground;
	transition: all $transition-fast;
	outline: none;

	&::placeholder {
		color: var(--tile-input-placeholder, #{$muted-foreground});
	}

	&:focus {
		outline: none;
		outline: var(--tile-input-focus-outline, none);
		outline-style: var(--tile-input-focus-outline-style, none);
		border-color: var(--tile-input-focus-border, #{$ring});
		box-shadow: var(--tile-input-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled,
	&.disabled {
		pointer-events: none;
		opacity: var(--tile-input-disabled-opacity, 0.5);
		cursor: not-allowed;
		background-color: var(--tile-input-disabled-background, #{$field-disabled});
		color: var(--tile-input-disabled-color, #{$foreground});
	}

	&.error {
		border-color: $destructive;
		box-shadow: var(--tile-input-error-shadow, none);

		&:focus {
			border-color: $destructive;
			box-shadow: var(--tile-input-error-focus-shadow, 0 0 0 1px #{$destructive});
		}
	}

	// Visual size is separate from the native HTML `size` attribute.
	&[data-control-size='xs'] {
		height: var(--tile-input-xs-height, 1.5rem);
		padding-inline: var(--tile-input-xs-padding-inline, #{$spacing-2});
		border-radius: var(--tile-input-xs-radius, #{$radius-sm});
		font-size: var(--tile-input-xs-font-size, #{$text-xs});
		line-height: var(--tile-input-compact-line-height, inherit);
		gap: var(--tile-input-compact-gap, normal);
	}

	&[data-control-size='sm'] {
		height: var(--tile-input-sm-height, 2rem);
		padding-inline: var(--tile-input-sm-padding-inline, #{$spacing-2});
		border-radius: var(--tile-input-sm-radius, #{$radius-sm});
		font-size: var(--tile-input-sm-font-size, #{$text-xs});
		line-height: var(--tile-input-compact-line-height, inherit);
		gap: var(--tile-input-compact-gap, normal);
	}

	&[data-control-size='lg'] {
		height: var(--tile-input-lg-height, 2.5rem);
		padding-inline: var(--tile-input-lg-padding-inline, #{$spacing-4});
		border-radius: var(--tile-input-lg-radius, #{$radius});
		font-size: var(--tile-input-lg-font-size, #{$text-base});
		gap: var(--tile-input-lg-gap, normal);
	}
}

.label {
	display: block;
	font-size: var(--tile-input-label-font-size, #{$text-sm});
	font-weight: $font-medium;
	color: $foreground;
	line-height: $leading-normal;

	&.required::after {
		content: ' *';
		color: $destructive;
	}
}

.helperText {
	font-size: var(--tile-input-description-font-size, #{$text-xs});
	color: var(--tile-input-description-color, #{$muted-foreground});
	line-height: var(--tile-input-description-line-height, #{$leading-normal});
}

.errorText {
	font-size: var(--tile-input-description-font-size, #{$text-xs});
	color: $destructive;
	line-height: var(--tile-input-description-line-height, #{$leading-normal});
}
